public function testFix(string $expected, ?string $input = null, array $configuration = []): void
{
    $this->fixer->configure($configuration);
    $this->doTest($expected, $input);
}

public function testWithWhitespacesConfig(string $expected, ?string $input = null): void
{
    $this->fixer->setWhitespacesConfig(new WhitespacesFixerConfig("\t", "\r\n"));

    $this->doTest($expected, $input);
}

public function testCommentBlockStartDetection(int $expected, string $code, int $index): void
{
    Tokens::clearCache();
    $tokens = Tokens::fromCode($code);

    $result = \Closure::bind(static fn (ClassAttributesSeparationFixer $fixer): int => $fixer->findCommentBlockStart($tokens, $index, 0), null, ClassAttributesSeparationFixer::class)($this->fixer);
    self::assertSame(
        $expected,
        $result,
        \sprintf('Expected index %d (%s) got index %d (%s).', $expected, $tokens[$expected]->toJson(), $result, $tokens[$result]->toJson()),
    );
}
